## 4. DYNAMIC ROUTES

### Dynamic Segments
```
app/blog/[slug]/page.tsx    → /blog/post-1
app/items/[id]/route.ts     → /items/123
```

### Catch-All Segments
```
app/docs/[...slug]/page.tsx → /docs/a/b/c → params: { slug: ['a', 'b', 'c'] }
```

### Optional Catch-All
```
app/docs/[[...slug]]/page.tsx → /docs or /docs/a/b/c
```

### Accessing Dynamic Parameters
```tsx
// In page or layout (Server Component)
export default async function Page({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  return <h1>{slug}</h1>
}

// In Client Component
'use client'
import { use } from 'react'

export default function Page({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params)
  return <h1>{slug}</h1>
}
```

### `generateStaticParams` (replaces `getStaticPaths`)
```tsx
export async function generateStaticParams() {
  return [
    { slug: 'post-1' },
    { slug: 'post-2' },
  ]
}

export default async function Page({ params }) {
  const { slug } = await params
  return <h1>Post: {slug}</h1>
}
```

### Dynamic Parameter Control (`dynamicParams`)
```tsx
export const dynamicParams = false // Return 404 for ungenerated params

export async function generateStaticParams() {
  return [{ id: '1' }, { id: '2' }]
}
```

