## 6. DATA FETCHING

### Server Component Fetching
```tsx
export default async function Page() {
  // Fetch with caching (static by default)
  const data = await fetch('https://api.example.com/posts')
  const posts = await data.json()

  return <ul>{posts.map(post => <li>{post.title}</li>)}</ul>
}
```

### Fetch Options & Caching

**Static (cached until revalidation)**:
```tsx
// Default behavior - cache indefinitely
const data = await fetch('https://api.example.com/posts', { 
  cache: 'force-cache' // explicit
})
```

**Dynamic (revalidate every request)**:
```tsx
// Equivalent to getServerSideProps
const data = await fetch('https://api.example.com/posts', {
  cache: 'no-store'
})
```

**Incremental Static Regeneration (revalidate after X seconds)**:
```tsx
// Equivalent to getStaticProps with revalidate
const data = await fetch('https://api.example.com/posts', {
  next: { revalidate: 60 } // revalidate every 60 seconds
})
```

### Migration from `getServerSideProps`
```tsx
// Pages Router
export async function getServerSideProps({ req, query }) {
  const authHeader = req.getHeaders()['authorization']
  const posts = await fetch(`https://.../posts`)
  return { props: { posts } }
}

export default function Page({ posts }) {
  return <div>{posts.map(p => <p>{p.title}</p>)}</div>
}

// App Router
import { headers } from 'next/headers'

export default async function Page() {
  const headersList = await headers()
  const authHeader = headersList.get('authorization')

  const res = await fetch(`https://.../posts`, { cache: 'no-store' })
  const posts = await res.json()

  return <div>{posts.map(p => <p>{p.title}</p>)}</div>
}
```

### Migration from `getStaticProps`
```tsx
// Pages Router
export async function getStaticProps() {
  const posts = await fetch('https://.../posts')
  return { props: { posts }, revalidate: 60 }
}

export default function Page({ posts }) {
  return <div>{posts.map(p => <p>{p.title}</p>)}</div>
}

// App Router
export default async function Page() {
  // Defaults to static caching
  const res = await fetch('https://.../posts', {
    next: { revalidate: 60 }
  })
  const posts = await res.json()

  return <div>{posts.map(p => <p>{p.title}</p>)}</div>
}
```

### ORM/Database Queries
```tsx
import { db, posts } from '@/lib/db'

export default async function Page() {
  const allPosts = await db.select().from(posts)
  return <ul>{allPosts.map(p => <li>{p.title}</li>)}</ul>
}
```

### Accessing Request Data
```tsx
import { cookies, headers } from 'next/headers'

export default async function Page() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const theme = cookieStore.get('theme')?.value
  const userAgent = headersList.get('user-agent')

  return <div>{theme}</div>
}
```

### Request Deduplication
```tsx
// React automatically deduplicates identical fetch requests in same render
const r1 = await fetch('https://.../user')
const r2 = await fetch('https://.../user') // Same URL, only fetched once
```

### Manual Caching with React.cache()
```tsx
import { cache } from 'react'

export const getPost = cache(async (id: string) => {
  return await db.query.posts.findFirst({
    where: eq(posts.id, parseInt(id))
  })
})

// getPost('1') only executes once per request, even if called multiple times
export default async function Page() {
  const post1 = await getPost('1')
  const post2 = await getPost('1') // Uses cached result
}
```

### Client Component Data Fetching (with `use` API)
```tsx
// Server Component passes promise
export default function Page() {
  const posts = getPosts() // Don't await!

  return (
    <Suspense fallback={<div>Loading...</div>}>
      <Posts posts={posts} />
    </Suspense>
  )
}

// Client Component resolves promise
'use client'
import { use } from 'react'

export default function Posts({ posts }: { posts: Promise<Post[]> }) {
  const allPosts = use(posts)
  return <ul>{allPosts.map(p => <li>{p.title}</li>)}</ul>
}
```

### Community Libraries (SWR, React Query)
```tsx
'use client'
import useSWR from 'swr'

export default function Page() {
  const { data, error, isLoading } = useSWR('/api/posts', fetcher)

  if (isLoading) return <div>Loading...</div>
  if (error) return <div>Error: {error.message}</div>

  return <ul>{data.map(p => <li>{p.title}</li>)}</ul>
}
```

