### Parallel Data Fetching
```tsx
// Don't wait sequentially - start both requests in parallel
export default async function Page() {
  const artistData = getArtist('user123')
  const albumsData = getAlbums('user123')

  const [artist, albums] = await Promise.all([artistData, albumsData])

  return <div>{artist.name}</div>
}
```

### Preloading Data
```tsx
const preload = (id: string) => {
  void getItem(id) // Start loading without awaiting
}

export default async function Page({ params }) {
  const { id } = await params
  preload(id) // Eagerly start loading

  const isAvailable = await checkAvailability()
  return isAvailable ? <Item id={id} /> : null
}

async function Item({ id }: { id: string }) {
  const item = await getItem(id) // Already cached from preload
  return <div>{item.name}</div>
}
```

