### Static Metadata (replaces `next/head`)
```tsx
import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'My Blog',
  description: 'Welcome to my blog',
  keywords: ['blog', 'next.js'],
  openGraph: {
    title: 'My Blog',
    description: 'Welcome to my blog',
    images: [{ url: '/og-image.jpg' }],
  }
}

export default function Page() {
  return <h1>Blog</h1>
