## 11. ROUTE HANDLERS (API Routes Replacement)

### Basic Route Handler
```tsx
// app/api/posts/route.ts
import { NextRequest } from 'next/server'

export async function GET(request: NextRequest) {
  return Response.json({ posts: [...] })
}

export async function POST(request: NextRequest) {
  const data = await request.json()
  // Create post
  return Response.json({ id: 1 }, { status: 201 })
}
```

### Supported HTTP Methods
```ts
export async function GET(request: NextRequest) {}
export async function POST(request: NextRequest) {}
export async function PUT(request: NextRequest) {}
export async function PATCH(request: NextRequest) {}
export async function DELETE(request: NextRequest) {}
export async function HEAD(request: NextRequest) {}
export async function OPTIONS(request: NextRequest) {}
```

### Accessing Request Data
```ts
export async function POST(request: NextRequest) {
  // JSON body
  const data = await request.json()

  // Form data
  const formData = await request.formData()

  // Query params
  const searchParams = request.nextUrl.searchParams
  const query = searchParams.get('query')

  // Headers
  const headersList = request.headers
  const userAgent = headersList.get('user-agent')

  // Cookies
  const token = request.cookies.get('token')

  return Response.json({ success: true })
}
```

### Dynamic Route Handlers
```ts
// app/items/[id]/route.ts
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  return Response.json({ id })
}
```

### Caching Route Handlers
```ts
// Static by default if using force-static
export const dynamic = 'force-static'

export async function GET() {
  const data = await fetch('https://...')
  return Response.json(data)
}

// Dynamic (request-time)
export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest) {
  return Response.json({ time: new Date() })
}

// Revalidate after X seconds
export const revalidate = 60

export async function GET() {
  const data = await fetch('https://...', { next: { revalidate: 60 } })
  return Response.json(data)
}
```

### `generateStaticParams` for Route Handlers
```ts
export async function generateStaticParams() {
  return [
    { id: '1' },
    { id: '2' },
  ]
}

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  return Response.json({ id })
}
```

### Reading Cookies
```ts
import { cookies } from 'next/headers'

export async function GET(request: NextRequest) {
  const cookieStore = await cookies()
  const token = cookieStore.get('token')

  // Or from request
  const tokenFromReq = request.cookies.get('token')

  // Set cookie in response
  const response = new Response('Hello')
  response.cookies.set('new', 'value')
  return response
}
```

### Setting Headers
```ts
export async function GET() {
  return new Response('Hello', {
    status: 200,
    headers: {
      'Content-Type': 'text/plain',
      'Custom-Header': 'value'
    }
  })
}
```

### CORS
```ts
export async function GET() {
  return new Response('Data', {
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE',
      'Access-Control-Allow-Headers': 'Content-Type',
    }
  })
}
```

### Redirects
```ts
import { redirect } from 'next/navigation'

export async function GET() {
  redirect('https://example.com')
}
```

### Streaming Responses
```ts
export async function GET() {
  const stream = new ReadableStream({
    async start(controller) {
      controller.enqueue(new TextEncoder().encode('data: chunk1\n'))
      controller.close()
    }
  })

  return new Response(stream, {
    headers: { 'Content-Type': 'text/event-stream' }
  })
}
```

### Webhooks
```ts
export async function POST(request: NextRequest) {
  try {
    const payload = await request.json()
    // Process webhook
    return Response.json({ success: true })
  } catch (error) {
    return Response.json(
      { error: error.message },
      { status: 400 }
    )
  }
}
```

